// P1AM-100 tank fill pump: low float on input 1, high float on input 2
#include <P1AM.h>
const int inSlot = 1;
const int outSlot = 2;
const int lowFloatPin = 1;
const int highFloatPin = 2;
const int pumpPin = 1;
bool pumpRunning = false;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // wait for the modules
  }
}

void loop() {
  bool lowFloat = P1.readDiscrete(inSlot, lowFloatPin); // ON when the water is low
  bool highFloat = P1.readDiscrete(inSlot, highFloatPin); // ON when the water is high
  if (lowFloat) {
    pumpRunning = true;
  } else if (highFloat) {
    pumpRunning = false;
  }
  P1.writeDiscrete(pumpRunning, outSlot, pumpPin); // the pump contactor
}

